&lt;/div&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Objets-Merveilleux.html&quot; title=&quot;Les Objets merveilleux&quot;&gt;Les objets merveilleux&lt;/a&gt;
        &lt;ul ID=&quot;OBJETSPAREMPLACEMENT&quot; CLASS=&quot;listecach&#233;e cadrebas&quot; style=&quot;font-size:100%&quot;&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Liste-Alphab&#233;tique-Des-Objets-Merveilleux.html&quot; title=&quot;Liste alphab&#233;tique des objets merveilleux&quot;&gt;Liste alphab&#233;tique&lt;/a&gt;&lt;/li&gt;
            &lt;li style=&quot;max-width:150px&quot;&gt;Listes par emplacement : &lt;a class=&quot;pagelink&quot; href=&quot;Objets-Merveilleux-Sans-Emplacement.html&quot; title=&quot;Objets merveilleux sans emplacement&quot;&gt;aucun&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Objets-Merveilleux-Sans-Emplacement-Liste.html&quot; title=&quot;Objets merveilleux sans emplacement liste&quot;&gt;avec profils&lt;/a&gt;), &lt;a class=&quot;pagelink&quot; href=&quot;Objets-Merveilleux-Port&#233;s-Sur-Le-Corps.html&quot; title=&quot;Objets merveilleux port&#233;s sur le corps&quot;&gt;corps&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Objets-Merveilleux-Port&#233;s-Autour-Du-Cou.html&quot; title=&quot;Objets merveilleux port&#233;s autour du cou&quot;&gt;cou&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Objets-Merveilleux-Port&#233;s-Sur-Les-&#201;paules.html&quot; title=&quot;Objets merveilleux port&#233;s sur les &#233;paules&quot;&gt;&#233;paules&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Objets-Merveilleux-Port&#233;s-Sur-Le-Front.html&quot; title=&quot;Objets merveilleux port&#233;s sur le front&quot;&gt;front&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Objets-Merveilleux-Port&#233;s-Aux-Mains.html&quot; title=&quot;Objets merveilleux port&#233;s aux mains&quot;&gt;mains&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Objets-Merveilleux-Port&#233;s-Aux-Pieds.html&quot; title=&quot;Objets merveilleux port&#233;s aux pieds&quot;&gt;pieds&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Objets-Merveilleux-Port&#233;s-Aux-Poignets.html&quot; title=&quot;Objets merveilleux port&#233;s aux poignets&quot;&gt;poignets&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Objets-Merveilleux-Port&#233;s-&#192;-La-Taille.html&quot; title=&quot;Objets merveilleux port&#233;s &#224; la taille&quot;&gt;taille&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Objets-Merveilleux-Port&#233;s-Sur-La-T&#234;te.html&quot; title=&quot;Objets merveilleux port&#233;s sur la t&#234;te&quot;&gt;t&#234;te&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Objets-Merveilleux-Port&#233;s-Sur-Le-Torse.html&quot; title=&quot;Objets merveilleux port&#233;s sur le torse&quot;&gt;torse&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Objets-Merveilleux-Port&#233;s-Sur-Les-Yeux.html&quot; title=&quot;Objets merveilleux port&#233;s sur les yeux&quot;&gt;yeux&lt;/a&gt;.&lt;/li&gt;&lt;/ul&gt;
    &lt;/li&gt;
    &lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Autels.html&quot; title=&quot;Les autels&quot;&gt;Les autels&lt;/a&gt;&lt;/li&gt;
        &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Implants-D&#233;moniaques.html&quot; title=&quot;Les implants d&#233;moniaques&quot;&gt;Les implants d&#233;moniaques&lt;/a&gt;&lt;/li&gt;
        &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pierre-Ioun.html&quot; title=&quot;Pierre ioun&quot;&gt;Les pierres ioun&lt;/a&gt;&lt;/li&gt;
        &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Talismans-Diaboliques.html&quot; title=&quot;Les talismans diaboliques&quot;&gt;Les talismans diaboliques&lt;/a&gt;&lt;/li&gt;
    &lt;/ul&gt;
&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Artefacts.html&quot; title=&quot;Les artefacts&quot;&gt;Les artefacts&lt;/a&gt;&lt;/li&gt;
    &lt;/ul&gt;
&lt;/td&gt;&lt;td&gt;
&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Objets-Intelligents.html&quot; title=&quot;Les objets intelligents&quot;&gt;Les objets intelligents&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Objets-Maudits.html&quot; title=&quot;Les objets maudits&quot;&gt;Les objets maudits&lt;/a&gt;&lt;/li&gt;
    &lt;/ul&gt;
&lt;ul&gt;&lt;li&gt;R&#232;gles g&#233;n&#233;rales&lt;/li&gt;
    &lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Des-Objets-Magiques.html&quot; title=&quot;Descriptions des objets magiques&quot;&gt;format&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;R&#232;gles-Relatives-Aux-Objets-Magiques.html&quot; title=&quot;R&#232;gles relatives aux objets magiques&quot;&gt;fonctionnement&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;ation-Dobjets-Magiques.html&quot; title=&quot;Cr&#233;ation d&amp;#39;objets magiques&quot;&gt;cr&#233;ation&lt;/a&gt;&lt;/li&gt;
    &lt;/ul&gt;
&lt;/ul&gt;
&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
&lt;/div&gt;
Ces objets sont des bottes, des fers &#224; cheval, des sandales, des chaussures, des pantoufles et tous les objets port&#233;s aux pieds.&lt;br /&gt;&lt;br /&gt;Tout le monde peut utiliser un objet merveilleux port&#233; aux pieds &#224; moins que le contraire ne soit indiqu&#233; dans sa description. Ces objets sont habituellement activ&#233;s par usage ou par un mot de commande mais il y a parfois des diff&#233;rences en fonction des objets.&lt;br /&gt;&lt;br /&gt;Tous les objets merveilleux d&#233;crits ci-dessous p&#232;sent entre 250 g et 2 kg, sauf certains &lt;i&gt;Fers &#224; cheval&lt;/i&gt; qui p&#232;sent 6 kg.&lt;br /&gt;&lt;br /&gt;&lt;script type=&quot;text/javascript&quot;&gt;
$(filtrable_init);

function filtrable_init() {
    // Find all tables with class filtrable and make them filtrable
    $(&quot;table.filtrable&quot;).each(makeFiltrable);
}

function makeFiltrable() {
    var table = $(this);
    var rows = table.find(&quot;tr&quot;);
    if (rows.length &lt; 2) {
        return;
    }
    var firstRow = rows.first();
    var cells = firstRow.children(&quot;td,th&quot;);
    table.get()[0].filters = [];
    cells.each(function (idx) {
        var contents = $(this).html;
        var filterLogo = $(&quot;&lt;img height=&#39;12px&#39; /&gt;&quot;);
        filterLogo.attr(&#39;src&#39;, &#39;/wiki/public/Upload/Battlemaps/Boutons/filter.png&#39;);
        filterLogo.attr(&#39;title&#39;, &#39;Cliquez ici pour filtrer les donn&#233;es&#39;);
        filterLogo.css(&#39;padding&#39;, &#39;0&#39;);
        filterLogo.click(doFilter(idx,filterLogo,table));
        $(this).prepend(filterLogo);
        table.get()[0].filters.push(null);
    });
}
function doFilter(nCol, logo, table) {
    return function () {
        var filter = prompt(&quot;Entrez le filtre &#224; appliquer.\nLaisser le cadre vide pour tout afficher; utilisez &#39;mot1|mot2&#39; pour un choix multiple.&quot;, &quot;&quot;).trim();
        if (filter == &quot;&quot;) {
            table.get()[0].filters[nCol] = null;
            logo.css(&quot;background-color&quot;, &quot;&quot;);
            logo.attr(&quot;title&quot;,&quot;Filtre actuel : aucun - cliquez pour changer le filtre&quot;);
        } else {
            table.get()[0].filters[nCol] = new RegExp(filter.trim(),&quot;i&quot;);
            logo.css(&quot;background-color&quot;, &quot;yellow&quot;);
            logo.attr(&quot;title&quot;,&quot;Filtre actuel : &quot; + (filter == &quot;&quot; ? &quot;aucun&quot; : filter)
                + &quot; - cliquez pour changer le filtre&quot;);
        }
        applyFilter(table);
    };
}
function applyFilter(table) {
    var rows = table.find(&quot;tr&quot;).filter(function (idx) {
        return idx &gt; 0 &amp;&amp; $(this).children(&quot;th&quot;).length == 0;
    });
    rows.each(function () {
        var keep = mustKeep(this,table.get()[0].filters);
        $(this).css(&quot;display&quot;, keep ? &quot;table-row&quot; : &quot;none&quot;);
    });
}
function mustKeep(row,filters) {
    var cells = $(row).children(&quot;td&quot;);
    var nCols = filters.length;
    var keep = true;
    var iCol = 0;
    while (keep &amp;&amp; iCol &lt; nCols) {
        keep = filters[iCol] === null ||
            cells.eq(iCol).html().match(filters[iCol]) != null;
        iCol++;
    }
    return keep;
}
&lt;/script&gt;
&lt;table CLASS=&quot;tablo centre autoalt toutgauche filtrable&quot;&gt;&lt;caption&gt;Objets merveilleux port&#233;s sur les pieds&lt;/caption&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td WIDTH=&quot;22%&quot;&gt;Objet&lt;/td&gt;&lt;td WIDTH= &quot;3%&quot;&gt;Source&lt;/td&gt;&lt;td WIDTH=&quot;65%&quot;&gt;Capacit&#233;s&lt;/td&gt;&lt;td WIDTH=&quot;10%&quot;&gt;Prix de vente&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bottes-Du-Chat.html&quot; title=&quot;Bottes du chat&quot;&gt;Bottes du chat&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le porteur subit les d&#233;g&#226;ts minimum (tous les d&#233;s donnent 1) lors d’une chute et retombe toujours sur ses pieds.&lt;/td&gt;&lt;td&gt;1 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bottes-De-Casse-Cou.html&quot; title=&quot;Bottes de casse-cou&quot;&gt;Bottes de casse-cou&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E, MR&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Jusqu’&#224; 10 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt; par jour, peuvent conf&#233;rer un bonus de comp&#233;tence de +5 aux tests d’&lt;a class=&quot;pagelink&quot; href=&quot;Acrobaties.html&quot; title=&quot;Acrobaties&quot;&gt;Acrobaties&lt;/a&gt; pour traverser une case menac&#233;e ou occup&#233;e. Chaque fois qu’un de ces tests est r&#233;ussit, le porteur obtient un bonus de +1 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#JETDATTAQUE&quot; title=&quot;Valeurs de combat&quot;&gt;jets d’attaque&lt;/a&gt; contre l’ennemi concern&#233; pendant son tour.&lt;/td&gt;&lt;td&gt;1 400 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bottes-Dendurance.html&quot; title=&quot;Bottes d’endurance&quot;&gt;Bottes d’endurance&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Les tests de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Constitution.html&quot; title=&quot;La Constitution&quot;&gt;Constitution&lt;/a&gt; pour r&#233;sister &#224; une &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;placements.html#MARCHEFORCEE&quot; title=&quot;Les d&#233;placements&quot;&gt;marche forc&#233;e&lt;/a&gt; sont moins difficiles, et s’ils sont &#233;chou&#233;s, infligent des d&#233;g&#226;ts non-l&#233;taux plut&#244;t que de la &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables.html#Fatigu&#233;&quot; title=&quot;Les &#233;tats pr&#233;judiciables&quot;&gt;fatigue&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;1 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bottes-Denthousiasme.html&quot; title=&quot;Bottes d&amp;#39;enthousiasme&quot;&gt;Bottes d’enthousiasme&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Trois fois par jour, permet d’accomplir l’exploit de bretteur &lt;a class=&quot;pagelink&quot; href=&quot;Exploits-(Bretteur).html#BRAVOURE&quot; title=&quot;Les exploits du bretteur&quot;&gt;bravoure&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;2 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bottes-Du-Titubant.html&quot; title=&quot;Bottes du titubant&quot;&gt;Bottes du titubant&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISG&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de +4 au &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Dmd.html&quot; title=&quot;DMD&quot;&gt;DMD&lt;/a&gt; contre les manœuvres de &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Bousculade.html&quot; title=&quot;bousculade&quot;&gt;bousculade&lt;/a&gt; et de &lt;a class=&quot;pagelink&quot; href=&quot;Croc-En-Jambe.html&quot; title=&quot;croc-en-jambe&quot;&gt;croc-en-jambe&lt;/a&gt;. Une fois par jour, permet de se d&#233;placer imm&#233;diatement &#224; une vitesse de 9 m. Le porteur ne provoque pas d&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Attaquedopportunite.html&quot; title=&quot;Attaque d&amp;#39;opportunit&#233; (redirection)&quot;&gt;attaque d&#39;opportunit&#233;&lt;/a&gt; en &lt;a class=&quot;pagelink&quot; href=&quot;Actions-De-Mouvement.html#SERELEVER&quot; title=&quot;Actions de mouvement&quot;&gt;se relevant&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;2 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pantoufles-De-D&#233;marche-A&#233;rienne.html&quot; title=&quot;Pantoufles de d&#233;marche a&#233;rienne&quot;&gt;Pantoufles de d&#233;marche a&#233;rienne&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Une fois par jour, le porteur ignore les &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;placement-Et-Position.html#TERRAINDIFFICILE&quot; title=&quot;D&#233;placement et position&quot;&gt;terrains difficiles&lt;/a&gt; (comme avec &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;marche-A&#233;rienne.html&quot; title=&quot;D&#233;marche a&#233;rienne&quot;&gt;d&#233;marche a&#233;rienne&lt;/a&gt;&lt;/i&gt;) et peut y faire des &lt;a class=&quot;pagelink&quot; href=&quot;Actions-Diverses.html#PASDEPLACEMENT&quot; title=&quot;Actions diverses&quot;&gt;pas de placement&lt;/a&gt;, pendant 10 minutes.&lt;/td&gt;&lt;td&gt;2 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bottes-Du-Terrain-Amical.html&quot; title=&quot;Bottes du terrain amical&quot;&gt;Bottes du terrain amical&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJRA, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Un &lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur.html&quot; title=&quot;Le r&#244;deur&quot;&gt;r&#244;deur&lt;/a&gt; ne laisse plus de traces derri&#232;re lui et obtient les bonus de l’&lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur.html#ENVIRONNEMENTDEPREDILECTION&quot; title=&quot;Le r&#244;deur&quot;&gt;environnement de pr&#233;dilection&lt;/a&gt; auquel ces bottes sont associ&#233;es (s’il les poss&#232;dent d&#233;j&#224;, ils augmentent de 2).&lt;/td&gt;&lt;td&gt;2 400 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bottes-De-Terres-Gel&#233;es.html&quot; title=&quot;Bottes de terres gel&#233;es&quot;&gt;Bottes de terres gel&#233;es&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;rent les effets du sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Endurance-Aux-&#201;nergies-Destructives.html&quot; title=&quot;Endurance aux &#233;nergies destructives&quot;&gt;endurance aux &#233;nergies destructives&lt;/a&gt;&lt;/i&gt; en permanence. Le porteur se d&#233;place normalement sans risque et sans laisser de traces sur les terrains glac&#233;s.&lt;/td&gt;&lt;td&gt;2 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bottes-Elfiques.html&quot; title=&quot;Bottes elfiques&quot;&gt;Bottes elfiques&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;rent un bonus de comp&#233;tence de +5 aux tests d’&lt;a class=&quot;pagelink&quot; href=&quot;Acrobaties.html&quot; title=&quot;Acrobaties&quot;&gt;Acrobaties&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;2 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Fers-&#192;-Cheval-De-Grand-Fardeau.html&quot; title=&quot;Fers &#224; cheval de grand fardeau&quot;&gt;Fers &#224; cheval de grand fardeau&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;RSE&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Double la &lt;a class=&quot;pagelink&quot; href=&quot;Poids-Transportable.html&quot; title=&quot;Poids transportable&quot;&gt;capacit&#233; de charge&lt;/a&gt; du porteur.&lt;/td&gt;&lt;td&gt;2 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chaussons-Dacrobate.html&quot; title=&quot;Chaussons d’acrobate&quot;&gt;Chaussons d’acrobate&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le porteur n’est pas &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables.html#Prisaud&#233;pourvu&quot; title=&quot;Les &#233;tats pr&#233;judiciables&quot;&gt;prit au d&#233;pourvu&lt;/a&gt; quand il escalade ou qu’il &#233;vite de tomber d’une surface &#233;troite/irr&#233;guli&#232;re. Conf&#232;rent un bonus de comp&#233;tence de +2 au &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Dmd.html&quot; title=&quot;DMD&quot;&gt;DMD&lt;/a&gt; contre les manœuvres de &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives.html#CROCENJAMBE&quot; title=&quot;Les manœuvres offensives&quot;&gt;croc-en-jambe&lt;/a&gt; et de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;R&#233;flexes&quot;&gt;R&#233;flexes&lt;/a&gt; pour &#233;viter de tomber.&lt;/td&gt;&lt;td&gt;3 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Fers-&#192;-Cheval-De-Rapidit&#233;.html&quot; title=&quot;Fers &#224; cheval de rapidit&#233;&quot;&gt;Fers &#224; cheval de rapidit&#233;&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;rent un bonus d’alt&#233;ration de +9 m &#224; la vitesse de d&#233;placement (la distance de saut augmente en proportion).&lt;/td&gt;&lt;td&gt;3 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bottes-De-Voltige.html&quot; title=&quot;Bottes de voltige&quot;&gt;Bottes de voltige&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Permet d’ignorer 3m de distance de chute suppl&#233;mentaires quand le porteur r&#233;ussit un test d’&lt;a class=&quot;pagelink&quot; href=&quot;Acrobaties.html&quot; title=&quot;Acrobaties&quot;&gt;Acrobaties&lt;/a&gt; pour amortir une chute. Une fois par &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt;, peuvent conf&#233;rer un bonus de comp&#233;tence de +10 &#224; un test d’&lt;a class=&quot;pagelink&quot; href=&quot;Acrobaties.html&quot; title=&quot;Acrobaties&quot;&gt;Acrobaties&lt;/a&gt; pour sauter tout en consid&#233;rant que le porteur a de l’&#233;lan. Conf&#232;rent un bonus de +10 aux tests d’&lt;a class=&quot;pagelink&quot; href=&quot;Acrobaties.html&quot; title=&quot;Acrobaties&quot;&gt;Acrobaties&lt;/a&gt; pour &#233;viter les &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Attaquedopportunite.html&quot; title=&quot;attaque d&amp;#39;opportunit&#233;&quot;&gt;attaques d’opportunit&#233;&lt;/a&gt; pour sauter ou se r&#233;&#233;quilibrer apr&#232;s atterrissage (effectuer plusieurs sauts de cette fa&#231;on dans la m&#234;me minute peut r&#233;duire la vitesse du porteur de moiti&#233;).&lt;/td&gt;&lt;td&gt;3 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bottes-Du-Bourbier.html&quot; title=&quot;Bottes du bourbier&quot;&gt;Bottes du bourbier&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;rent un bonus de r&#233;sistance de +2 aux jets de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Vigueur&quot;&gt;Vigueur&lt;/a&gt; pour r&#233;sister aux poisons et aux maladies. Le porteur se d&#233;place normalement sans risque et sans laisser de traces sur les terrains mar&#233;cageux, et ignore les g&#234;nes occasionn&#233;es par les pr&#233;cipitations m&#233;t&#233;orologiques.&lt;/td&gt;&lt;td&gt;3 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bottes-De-Cambrioleur.html&quot; title=&quot;Bottes de cambrioleur&quot;&gt;Bottes de cambrioleur&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;rent un bonus de comp&#233;tence de +5 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt;, &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt;, et aux jets de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;R&#233;flexes&quot;&gt;R&#233;flexes&lt;/a&gt; pour d&#233;tecter/r&#233;sister aux pi&#232;ges fix&#233;s au sol.&lt;/td&gt;&lt;td&gt;4 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; &lt;a class=&quot;pagelink&quot; href=&quot;Bottes-De-Cambrioleur-Sup&#233;rieures.html&quot; title=&quot;Bottes de cambrioleur sup&#233;rieures&quot;&gt;Bottes de cambrioleur sup&#233;rieures&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Fonctionnent comme les &lt;i&gt;Bottes de Cambrioleur&lt;/i&gt;, mais le bonus s’&#233;l&#232;ve &#224; +10 et, une fois par jour, permettent peut lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;tection-Des-Pi&#232;ges.html&quot; title=&quot;D&#233;tection des pi&#232;ges&quot;&gt;d&#233;tection des pi&#232;ges&lt;/a&gt;&lt;/i&gt;.&lt;/td&gt;&lt;td&gt;| 46 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bottes-De-La-Rose-&#201;ternelle.html&quot; title=&quot;Bottes de la Rose &#233;ternelle&quot;&gt;Bottes de la Rose &#233;ternelle&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;D&amp;M, &lt;i&gt;ISG&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de comp&#233;tence de +2 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Discr&#233;tion.html&quot; title=&quot;Discr&#233;tion&quot;&gt;Discr&#233;tion&lt;/a&gt; et de &lt;a class=&quot;pagelink&quot; href=&quot;Repr&#233;sentation.html&quot; title=&quot;Repr&#233;sentation&quot;&gt;Repr&#233;sentation&lt;/a&gt; (danse). Permet de se d&#233;placer normalement dans les zones couvertes de fleurs non-magiques. Un suivant de &lt;a class=&quot;pagelink&quot; href=&quot;Sh&#233;lyn-(Technique).html&quot; title=&quot;Sh&#233;lyn&quot;&gt;Sh&#233;lyn&lt;/a&gt; peut lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;H&#233;b&#233;tement-De-Monstre.html&quot; title=&quot;H&#233;b&#233;tement de monstre&quot;&gt;h&#233;b&#233;tement de monstre&lt;/a&gt;&lt;/i&gt; une fois par jour, et convoquer une magnifique fleur non-magique qui dure 1 jour.&lt;/td&gt;&lt;td&gt;4 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Fers-&#192;-Cheval-De-Ruade-D&#233;vastatrice.html&quot; title=&quot;Fers &#224; cheval de ruade d&#233;vastatrice&quot;&gt;Fers &#224; cheval de ruade d&#233;vastatrice&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E, MR&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;rent un bonus d’alt&#233;ration aux jets d’attaque et de d&#233;g&#226;ts et/ou une propri&#233;t&#233; sp&#233;ciale aux attaques de sabot. Peuvent &#234;tre construits en &lt;a class=&quot;pagelink&quot; href=&quot;Mat&#233;riaux-Sp&#233;ciaux.html&quot; title=&quot;Les mat&#233;riaux sp&#233;ciaux&quot;&gt;mat&#233;riaux sp&#233;ciaux&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +1&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus maximal s’&#233;l&#232;ve &#224; +1.&lt;/td&gt;&lt;td&gt;4 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +2&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus maximal s’&#233;l&#232;ve &#224; +2.&lt;/td&gt;&lt;td&gt;| 16 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +3&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus maximal s’&#233;l&#232;ve &#224; +3.&lt;/td&gt;&lt;td&gt;| 36 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +4&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus maximal s’&#233;l&#232;ve &#224; +4.&lt;/td&gt;&lt;td&gt;| 64 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +5&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus maximal s’&#233;l&#232;ve &#224; +5.&lt;/td&gt;&lt;td&gt;| 100 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sandales-R&#233;actives.html&quot; title=&quot;Sandales r&#233;actives&quot;&gt;Sandales r&#233;actives&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le porteur peut effectuer une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt; et une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Mouvement.html&quot; title=&quot;Action de mouvement&quot;&gt;action de mouvement&lt;/a&gt; pendant les &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;roulement-Dun-Combat.html#SURPRISE&quot; title=&quot;Le d&#233;roulement d&amp;#39;un combat&quot;&gt;rounds de surprise&lt;/a&gt; (s’il en est d&#233;j&#224; capable, il obtient un bonus de circonstance de +3 m &#224; sa vitesse de base pendant ces &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt;).&lt;/td&gt;&lt;td&gt;4 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chaussons-De-Marche-Brumeuse.html&quot; title=&quot;Chaussons de marche brumeuse&quot;&gt;Chaussons de marche brumeuse&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Jusqu’&#224; 10 minutes par jour, peuvent conf&#233;rer les effets de &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Marche-Dans-Les-Airs.html&quot; title=&quot;Marche dans les airs&quot;&gt;marche dans les airs&lt;/a&gt;&lt;/i&gt;, mais uniquement dans les brumes ou les brouillards (magiques et naturels).&lt;/td&gt;&lt;td&gt;4 400 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chaussons-Daraign&#233;e.html&quot; title=&quot;Chaussons d&amp;#39;araign&#233;e&quot;&gt;Chaussons d’araign&#233;e&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Jusqu’&#224; 10 minutes par jour, permettent de marcher au mur et au plafond avec une vitesse de 6 m.&lt;/td&gt;&lt;td&gt;4 800 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bottes-Telluriques.html&quot; title=&quot;Bottes telluriques&quot;&gt;Bottes telluriques&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISG&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Peut conf&#233;rer une &lt;a class=&quot;pagelink&quot; href=&quot;Gu&#233;rison-Acc&#233;l&#233;r&#233;e-(Capacit&#233;).html&quot; title=&quot;Gu&#233;rison acc&#233;l&#233;r&#233;e (Ext)&quot;&gt;gu&#233;rison acc&#233;l&#233;r&#233;e&lt;/a&gt; 1 ainsi qu&#39;un bonus de +4 au &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Dmd.html&quot; title=&quot;DMD&quot;&gt;DMD&lt;/a&gt; contre les manœuvres offensives de &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Bousculade.html&quot; title=&quot;bousculade&quot;&gt;bousculade&lt;/a&gt;, de &lt;a class=&quot;pagelink&quot; href=&quot;Croc-En-Jambe.html&quot; title=&quot;croc-en-jambe&quot;&gt;croc-en-jambe&lt;/a&gt; et de &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Repositionnement.html&quot; title=&quot;repositionnement&quot;&gt;repositionnement&lt;/a&gt; si le porteur reste immobile.&lt;/td&gt;&lt;td&gt;5 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sandales-De-L&#233;g&#232;ret&#233;-A&#233;rienne.html&quot; title=&quot;Sandales de l&#233;g&#232;ret&#233; a&#233;rienne&quot;&gt;Sandales de l&#233;g&#232;ret&#233; a&#233;rienne&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E, RSE&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Cinq fois par jour, si le porteur s’est d&#233;placer d’au moins 3 m sur une surface solide, il peut profiter des effets du sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Marche-Dans-Les-Airs.html&quot; title=&quot;Marche dans les airs&quot;&gt;marche dans les airs&lt;/a&gt;&lt;/i&gt; jusqu’&#224; la fin du round.&lt;/td&gt;&lt;td&gt;5 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bottes-De-Sept-Lieues.html&quot; title=&quot;Bottes de sept lieues&quot;&gt;Bottes de sept lieues&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;rent un bonus d’alt&#233;ration de +3 m &#224; la vitesse de base au sol et un bonus de comp&#233;tence de +5 aux tests d’&lt;a class=&quot;pagelink&quot; href=&quot;Acrobaties.html&quot; title=&quot;Acrobaties&quot;&gt;Acrobaties&lt;/a&gt; pour sauter.&lt;/td&gt;&lt;td&gt;5 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Fers-&#192;-Cheval-Du-Z&#233;phyr.html&quot; title=&quot;Fers &#224; cheval du z&#233;phyr&quot;&gt;Fers &#224; cheval du z&#233;phyr&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le porteur se d&#233;place normalement sans risque et sans laisser de traces sur les terrains instables ou trop peu solides pour supporter son poids.&lt;/td&gt;&lt;td&gt;6 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Souliers-Hant&#233;s.html&quot; title=&quot;Souliers hant&#233;s&quot;&gt;Souliers hant&#233;s&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Deux fois par jour, permettent de convoquer 1d4 &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Serviteur-Invisible.html&quot; title=&quot;Serviteur invisible&quot;&gt;serviteur(s) invisible(s)&lt;/a&gt;&lt;/i&gt; pendant 3 heures. Une fois par jour, peuvent conf&#233;rer un &lt;a class=&quot;pagelink&quot; href=&quot;Modificateurs-De-Combat.html#CAMOUFLAGE&quot; title=&quot;Modificateurs de combat&quot;&gt;camouflage&lt;/a&gt; de 20% pendant 3 minutes.&lt;/td&gt;&lt;td&gt;6 480 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bottes-D&#233;chapp&#233;e.html&quot; title=&quot;Bottes d’&#233;chapp&#233;e&quot;&gt;Bottes d’&#233;chapp&#233;e&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Trois fois par jour, permettent de se d&#233;placer de 4,50 m au par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Mouvement.html&quot; title=&quot;Action de mouvement&quot;&gt;action de mouvement&lt;/a&gt;, sans provoquer d’&lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Attaquedopportunite.html&quot; title=&quot;attaque d&amp;#39;opportunit&#233;&quot;&gt;attaques d’opportunit&#233;&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;7 200 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bottes-De-L&#233;vitation.html&quot; title=&quot;Bottes de l&#233;vitation&quot;&gt;Bottes de l&#233;vitation&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;rent les effets du sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;L&#233;vitation.html&quot; title=&quot;L&#233;vitation&quot;&gt;l&#233;vitation&lt;/a&gt;&lt;/i&gt; &#224; volont&#233;.&lt;/td&gt;&lt;td&gt;7 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bottes-De-Prompte-Fureur.html&quot; title=&quot;Bottes de prompte fureur&quot;&gt;Bottes de prompte fureur&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;rent un bonus d’alt&#233;ration de +3m &#224; la vitesse de base. Un porteur en &lt;a class=&quot;pagelink&quot; href=&quot;Barbare.html#RAGE&quot; title=&quot;Le barbare&quot;&gt;barbare&lt;/a&gt; b&#233;n&#233;ficie d’un bonus de parade de +4 &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt; contre les &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Attaquedopportunite.html&quot; title=&quot;attaque d&amp;#39;opportunit&#233;&quot;&gt;attaques d’opportunit&#233;&lt;/a&gt; provoqu&#233;es en traversant/quittant un espace contr&#244;l&#233; ou en lan&#231;ant un sort.&lt;/td&gt;&lt;td&gt;7 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bottes-Denracinement.html&quot; title=&quot;Bottes d’enracinement&quot;&gt;Bottes d’enracinement&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;rent un bonus de circonstance cumulatif de +1 au &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Dmd.html&quot; title=&quot;DMD&quot;&gt;DMD&lt;/a&gt; pour chaque &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt; sans d&#233;placement.&lt;/td&gt;&lt;td&gt;8 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bottes-D&#233;vasion.html&quot; title=&quot;Bottes d’&#233;vasion&quot;&gt;Bottes d’&#233;vasion&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E, MR&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Une fois par jour, lorsque le porteur est &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables.html#Agripp&#233;&quot; title=&quot;Les &#233;tats pr&#233;judiciables&quot;&gt;agripp&#233;&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables.html#Immobilis&#233;&quot; title=&quot;Les &#233;tats pr&#233;judiciables&quot;&gt;immobilis&#233;&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables.html#Enchev&#234;tr&#233;&quot; title=&quot;Les &#233;tats pr&#233;judiciables&quot;&gt;enchev&#234;tr&#233;&lt;/a&gt;, il peut se t&#233;l&#233;porter &#224; 9 m de sa position (120 m ou moins si le porteur est un gnome) (comme avec &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Porte-Dimensionnelle.html&quot; title=&quot;Porte dimensionnelle&quot;&gt;porte dimensionnelle&lt;/a&gt;&lt;/i&gt;).&lt;/td&gt;&lt;td&gt;8 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bottes-Cauchemardesque.html&quot; title=&quot;Bottes cauchemardesque&quot;&gt;Bottes cauchemardesque&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;rent un &lt;a class=&quot;pagelink&quot; href=&quot;Modificateurs-De-Combat.html#CAMOUFLAGE&quot; title=&quot;Modificateurs de combat&quot;&gt;camouflage&lt;/a&gt; de 20% quand le porteur &lt;a class=&quot;pagelink&quot; href=&quot;Actions-Complexes.html#COURIR&quot; title=&quot;Actions complexes&quot;&gt;court&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;Actions-Sp&#233;ciales.html#CHARGE&quot; title=&quot;Actions sp&#233;ciales&quot;&gt;charge&lt;/a&gt;. Trois fois par jour, peut conf&#233;rer un &lt;a class=&quot;pagelink&quot; href=&quot;Modificateurs-De-Combat.html#CAMOUFLAGE&quot; title=&quot;Modificateurs de combat&quot;&gt;camouflage&lt;/a&gt; de 20% pendant 1 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt;. Une fois par jour, lorsqu’il r&#233;ussit une attaque au corps &#224; corps, le porteur peut faire des d&#233;g&#226;ts de feu autour de lui.&lt;/td&gt;&lt;td&gt;8 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bottes-De-Collision.html&quot; title=&quot;Bottes de collision&quot;&gt;Bottes de collision&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CM&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de +2 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdattaque.html&quot; title=&quot;jet dattaque&quot;&gt;jets d&#39;attaque&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#DEGATS&quot; title=&quot;Valeurs de combat&quot;&gt;de d&#233;g&#226;ts&lt;/a&gt; lors d&#39;une &lt;a class=&quot;pagelink&quot; href=&quot;Actions-Sp&#233;ciales#Charge.html&quot; title=&quot;charge&quot;&gt;charge&lt;/a&gt;. Une fois par jour, permet de bousculer de 3 m une cr&#233;ature de taille G ou moins au touch&#233;, la faisant tomber &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#&#192;terre.html&quot; title=&quot;&#192; terre&quot;&gt;&#224; terre&lt;/a&gt; apr&#232;s le mouvement.&lt;/td&gt;&lt;td&gt;8 800 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Fers-&#192;-Cheval-Cauchemardesque.html&quot; title=&quot;Fers &#224; cheval cauchemardesque&quot;&gt;Fers &#224; cheval cauchemardesque&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Jusqu’&#224; 10 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt; par jour, peuvent conf&#233;rer le pouvoir &lt;a class=&quot;pagelink&quot; href=&quot;Destrier-Noir.html&quot; title=&quot;Destrier noir&quot;&gt;fum&#233;e&lt;/a&gt; et ajouter 1d4 d&#233;g&#226;ts de feu aux attaques de sabots.&lt;/td&gt;&lt;td&gt;9 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bottes-&#192;-Chausse-Trappes.html&quot; title=&quot;Bottes &#224; chausse-trappes&quot;&gt;Bottes &#224; chausse-trappes&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Jusqu’&#224; 10 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt; par jour, peuvent poser des &lt;a class=&quot;pagelink&quot; href=&quot;Chausse-Trappes-(Objet).html&quot; title=&quot;Chausse-trappes&quot;&gt;chausses-trappes&lt;/a&gt; sur le chemin du porteur.&lt;/td&gt;&lt;td&gt;10 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bottes-De-Perception-Des-Vibrations.html&quot; title=&quot;Bottes de perception des vibrations&quot;&gt;Bottes de perception des vibrations&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;rent la &lt;a class=&quot;pagelink&quot; href=&quot;Perception-Des-Vibrations-(Capacit&#233;).html&quot; title=&quot;Perception des vibrations (Ext)&quot;&gt;perception des vibrations&lt;/a&gt; (1,50 m) en permanence.&lt;/td&gt;&lt;td&gt;10 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bottes-Du-Mastodonte.html&quot; title=&quot;Bottes du mastodonte&quot;&gt;Bottes du mastodonte&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;rent un bonus d’alt&#233;ration de +2 aux tentatives de &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives.html#RENVERSEMENT&quot; title=&quot;Les manœuvres offensives&quot;&gt;renversement&lt;/a&gt; et un bonus d’esquive de +2 &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt; quand il effectue cette manœuvre. Infligent un malus de -2 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Discr&#233;tion.html&quot; title=&quot;Discr&#233;tion&quot;&gt;Discr&#233;tion&lt;/a&gt;. Une fois par jour, permettent d’effectuer une attaque de &lt;a class=&quot;pagelink&quot; href=&quot;Pi&#233;tinement-(Capacit&#233;).html&quot; title=&quot;Pi&#233;tinement (Ext)&quot;&gt;pi&#233;tinement&lt;/a&gt; (2d8+18) &#224; une cr&#233;ature de taille G ou moins.&lt;/td&gt;&lt;td&gt;10 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chaussures-D&#233;clairs-Bondissants.html&quot; title=&quot;Chaussures d’&#233;clairs bondissants&quot;&gt;Chaussures d’&#233;clairs bondissants&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Une fois par jour, le porteur peut se d&#233;placer en ligne droite (15 m maximum) sans provoquer d’&lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#ATTAQUEDOPPORTUNITE&quot; title=&quot;Valeurs de combat&quot;&gt;attaques d’opportunit&#233;&lt;/a&gt; et en infligeant des d&#233;g&#226;ts d’&#233;lectricit&#233; aux objets et aux cr&#233;atures sur son passage.&lt;/td&gt;&lt;td&gt;10 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bottes-De-Rapidit&#233;.html&quot; title=&quot;Bottes de rapidit&#233;&quot;&gt;Bottes de rapidit&#233;&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Jusqu’&#224; 10 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt; par jour, peuvent conf&#233;rer les effets du sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Rapidit&#233;.html&quot; title=&quot;Rapidit&#233;&quot;&gt;rapidit&#233;&lt;/a&gt;&lt;/i&gt;.&lt;/td&gt;&lt;td&gt;12 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bottes-Verdoyantes.html&quot; title=&quot;Bottes verdoyantes&quot;&gt;Bottes verdoyantes&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Trois fois par jour, peuvent faire pousser assez de nourriture pour 2 cr&#233;atures de taille M pour une journ&#233;e sous les pieds du porteurs, rendant le terrain &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;placement-Et-Position.html#TERRAINDIFFICILE&quot; title=&quot;D&#233;placement et position&quot;&gt;difficile&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;12 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bottes-Ail&#233;es.html&quot; title=&quot;Bottes ail&#233;es&quot;&gt;Bottes ail&#233;es&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Trois fois par jour, peuvent conf&#233;rer les effets du sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sort-Vol.html&quot; title=&quot;Vol&quot;&gt;vol&lt;/a&gt;&lt;/i&gt; (avec un bonus aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Vol.html&quot; title=&quot;Vol&quot;&gt;Vol&lt;/a&gt; de +4) pendant 5 minutes.&lt;/td&gt;&lt;td&gt;16 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bottes-De-Ciel-Et-Terre.html&quot; title=&quot;Bottes de ciel et terre&quot;&gt;Bottes de ciel et terre&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CMy&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Fonctionnent comme des &lt;a class=&quot;pagelink&quot; href=&quot;Bottes-Ail&#233;es.html&quot; title=&quot;Bottes ail&#233;es&quot;&gt;bottes ail&#233;es&lt;/a&gt;, mais conf&#232;rent un bonus de +5 au &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Dmd.html&quot; title=&quot;DMD&quot;&gt;DMD&lt;/a&gt; contre certaines manoeuvres offensives tant que le porteur est sur terre. Au prix d&#39;une utilisation de &lt;a class=&quot;pagelink&quot; href=&quot;Glossaire-Mythique#Pouvoirmythique.html&quot; title=&quot;pouvoir mythique&quot;&gt;pouvoir mythique&lt;/a&gt;, le bonus au DMD peut persister dans les airs.&lt;/td&gt;&lt;td&gt;20 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chaussures-De-Marche-Sur-Le-Feu.html&quot; title=&quot;Chaussures de marche sur le feu&quot;&gt;Chaussures de marche sur le feu&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;rent une r&#233;sistance au feu de 10 et les effets du sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Marche-Sur-Londe.html&quot; title=&quot;Marche sur l&amp;#39;onde&quot;&gt;marche sur l’onde&lt;/a&gt;&lt;/i&gt; sur la lave et le magma en permanence.&lt;/td&gt;&lt;td&gt;21 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sandales-Des-Dryades.html&quot; title=&quot;Sandales des dryades&quot;&gt;Sandales des dryades&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;rent la capacit&#233; &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html#DEPLACEMENTFACILITE&quot; title=&quot;Le druide&quot;&gt;d&#233;placement facilit&#233;&lt;/a&gt;. Dans les for&#234;ts, conf&#232;rent un bonus de comp&#233;tence de +2 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Discr&#233;tion.html&quot; title=&quot;Discr&#233;tion&quot;&gt;Discr&#233;tion&lt;/a&gt;, et font dispara&#238;tre les traces et les odeurs du porteur. Une fois par jour, permettent de demeurer dans un arbre jusqu’&#224; 9 heures ou de se t&#233;l&#233;porter &#224; un arbre similaire (comme avec &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Voyage-Par-Les-Arbres.html&quot; title=&quot;Voyage par les arbres&quot;&gt;voyage par les arbres&lt;/a&gt;&lt;/i&gt;).&lt;/td&gt;&lt;td&gt;24 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Fers-&#192;-Cheval-De-Brume.html&quot; title=&quot;Fers &#224; cheval de brume&quot;&gt;Fers &#224; cheval de brume&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Jusqu’&#224; 10 minutes par jour, peuvent conf&#233;rer les effets du sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;tat-Gazeux.html&quot; title=&quot;&#201;tat gazeux&quot;&gt;&#233;tat gazeux&lt;/a&gt;&lt;/i&gt; au porteur et &#224; son cavalier tant que ce dernier ne quitte pas le porteur.&lt;/td&gt;&lt;td&gt;27 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bottes-Descampette.html&quot; title=&quot;Bottes d’escampette&quot;&gt;Bottes d’escampette&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Une fois par jour, le porteur peut lier une case de 1,5 m de c&#244;t&#233; &#224; ces bottes. Il peut se t&#233;l&#233;porter &#224; cette case li&#233;e d’o&#249; il veut par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Complexe.html&quot; title=&quot;Action complexe&quot;&gt;action complexe&lt;/a&gt; (comme avec &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Poudre-Descampette.html&quot; title=&quot;Poudre d&amp;#39;escampette&quot;&gt;poudre d’escampette&lt;/a&gt;&lt;/i&gt;).&lt;/td&gt;&lt;td&gt;30 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bottes-Du-H&#233;raut-Des-Batailles.html&quot; title=&quot;Bottes du h&#233;raut des batailles&quot;&gt;Bottes du h&#233;raut des batailles&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Une fois par jour, peuvent conf&#233;rer les effets du sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;H&#233;ro&#239;sme-Supr&#234;me.html&quot; title=&quot;H&#233;ro&#239;sme supr&#234;me&quot;&gt;h&#233;ro&#239;sme supr&#234;me&lt;/a&gt;&lt;/i&gt; pendant 11 minutes.&lt;/td&gt;&lt;td&gt;30 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Fers-&#192;-Cheval-Glorieux.html&quot; title=&quot;Fers &#224; cheval glorieux&quot;&gt;Fers &#224; cheval glorieux&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Une fois par jour, le cavalier du porteur peut augmenter la taille de ce dernier d’une cat&#233;gorie ou changer son type (comme avec &lt;a class=&quot;pagelink&quot; href=&quot;Forme-Bestiale-Iv.html&quot; title=&quot;Forme bestiale IV&quot;&gt;forme bestiale IV&lt;/a&gt;). Tant qu’elle profite d’un de ces effets, elle gagne une &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;duction-De-D&#233;g&#226;ts-(Capacit&#233;).html&quot; title=&quot;RD&quot;&gt;RD&lt;/a&gt; 5/alignement choisi.&lt;/td&gt;&lt;td&gt;39 600 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bottes-D&#233;vasion-Fi&#233;lonne.html&quot; title=&quot;Bottes d&amp;#39;&#233;vasion fi&#233;lonne&quot;&gt;Bottes d&#39;&#233;vasion fi&#233;lonne&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISR&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Une fois par jour, permet d&#39;utiliser &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Nappe-De-Brouillard.html&quot; title=&quot;Nappe de brouillard&quot;&gt;nappe de brouillard&lt;/a&gt;&lt;/i&gt; par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Rapide.html&quot; title=&quot;Action rapide&quot;&gt;action rapide&lt;/a&gt;. Un porteur &lt;a class=&quot;pagelink&quot; href=&quot;Tieffelin-(Race).html&quot; title=&quot;Les tieffelins&quot;&gt;tieffelin&lt;/a&gt; peut se t&#233;l&#233;porter dans un rayon de 300 m&#232;tres (comme avec &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Porte-Dimensionnelle.html&quot; title=&quot;Porte dimensionnelle&quot;&gt;porte dimensionnelle&lt;/a&gt;&lt;/i&gt;) lorsqu&#39;il utilise cette capacit&#233;.&lt;/td&gt;&lt;td&gt;45 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bottes-De-T&#233;l&#233;portation.html&quot; title=&quot;Bottes de t&#233;l&#233;portation&quot;&gt;Bottes de t&#233;l&#233;portation&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Trois fois par jour, permettent de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;T&#233;l&#233;portation.html&quot; title=&quot;T&#233;l&#233;portation&quot;&gt;t&#233;l&#233;portation&lt;/a&gt;&lt;/i&gt;.&lt;/td&gt;&lt;td&gt;49 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chaussons-Du-Triton.html&quot; title=&quot;Chaussons du triton&quot;&gt;Chaussons du triton&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E, MR&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Permettent de respirer sous l’eau et conf&#232;rent une vitesse de nage de 9 m (s’il en est d&#233;j&#224; capable, il obtient un bonus d’alt&#233;ration de +3 m &#224; sa vitesse de nage).&lt;/td&gt;&lt;td&gt;56 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bottes-De-Grand-Pas.html&quot; title=&quot;Bottes de grand-pas&quot;&gt;Bottes de grand-pas&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CMy&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Fonctionnent comme des &lt;a class=&quot;pagelink&quot; href=&quot;Bottes-De-Rapidit&#233;.html&quot; title=&quot;Bottes de rapidit&#233;&quot;&gt;bottes de rapidit&#233;&lt;/a&gt; et des &lt;a class=&quot;pagelink&quot; href=&quot;Bottes-De-Sept-Lieues.html&quot; title=&quot;Bottes de sept lieues&quot;&gt;bottes de sept lieues&lt;/a&gt;. Au prix d&#39;une utilisation de &lt;a class=&quot;pagelink&quot; href=&quot;Glossaire-Mythique#Pouvoirmythique.html&quot; title=&quot;pouvoir mythique&quot;&gt;pouvoir mythique&lt;/a&gt;, permet de se t&#233;l&#233;porter (comme avec &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;T&#233;l&#233;portation.html&quot; title=&quot;T&#233;l&#233;portation&quot;&gt;t&#233;l&#233;portation&lt;/a&gt;&lt;/i&gt;) sur une distance ininterrompue de 33km maximum (si un obstacle l&#39;interrompt, le porteur s&#39;arr&#234;te face &#224; lui).&lt;/td&gt;&lt;td&gt;80 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Fers-&#192;-Cheval-De-La-Fureur-Du-D&#233;sert.html&quot; title=&quot;Fers &#224; cheval de la fureur du d&#233;sert&quot;&gt;Fers &#224; cheval de la fureur du d&#233;sert&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISR&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Jusqu&#39;&#224; 80 minutes par jour (en tranches de 10 minutes), peut transformer les sabots du porteur en &lt;i&gt;armes de &lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armes#Feu.html&quot; title=&quot;feu (propri&#233;t&#233;)&quot;&gt;feu&lt;/a&gt; +1&lt;/i&gt;. Trois fois par jour, un porteur ou cavalier k&#233;l&#233;shite peut utiliser un &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Brouillard-Dense.html&quot; title=&quot;Brouillard dense&quot;&gt;brouillard dense&lt;/a&gt;&lt;/i&gt; qui ne s&#39;active que lorsqu&#39;il quitte la zone d&#39;effet et rend les cr&#233;atures fi&#233;vreuses.&lt;/td&gt;&lt;td&gt;88 000 po&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
